// Full-page adaptation of the supplied InteractiveStarfieldHero.
(()=>{const canvas=document.querySelector('#starfield'),ctx=canvas.getContext('2d');if(!ctx)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');let w=0,h=0,stars=[],raf=0,influence=0,last=0;const mouse={x:-9999,y:-9999,active:false};
function resize(){w=innerWidth;h=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:Math.max(90,Math.min(340,Math.round(w*h/3100)))},()=>{const x=Math.random()*w,y=Math.random()*h;return{ox:x,oy:y,x,y,vx:0,vy:0,r:.8+Math.random()*1.4,alpha:.12+Math.random()*.55,phase:Math.random()*Math.PI*2,rot:Math.random()*Math.PI*2}});if(reduced.matches)draw(performance.now());}
function draw(now){ctx.clearRect(0,0,w,h);const dt=Math.min(2,last?(now-last)/16.667:1);last=now;const active=mouse.active&&!reduced.matches;influence=Math.max(0,Math.min(1,influence+(active?.06:-.03)*dt));for(const s of stars){const dx=s.x-mouse.x,dy=s.y-mouse.y,dist=Math.hypot(dx,dy),t=influence>.01&&dist<160?(1-dist/160)**2*influence:0;if(!reduced.matches){if(t>.01&&dist>.1){s.vx+=dx/dist*1.8*t*dt;s.vy+=dy/dist*1.8*t*dt}s.vx+=(s.ox-s.x)*.056*dt;s.vy+=(s.oy-s.y)*.056*dt;s.vx*=Math.pow(.835,dt);s.vy*=Math.pow(.835,dt);s.x+=s.vx*dt;s.y+=s.vy*dt}const twinkle=reduced.matches?.65:Math.sin(now/1000*1.4+s.phase)*.5+.5;ctx.globalAlpha=Math.min(1,s.alpha*(.55+twinkle*.45)+t);ctx.fillStyle=`rgb(${Math.round(177+78*t)},${Math.round(105+132*t)},255)`;ctx.save();ctx.translate(s.x,s.y);ctx.rotate(Math.hypot(s.vx,s.vy)>.3?Math.atan2(s.vy,s.vx)+Math.PI/2:s.rot);if(t>.4){ctx.shadowBlur=6+t*10;ctx.shadowColor=ctx.fillStyle}const ww=s.r*2,hh=s.r*2+t*18;ctx.beginPath();ctx.roundRect(-ww/2,-hh/2,ww,hh,Math.min(ww,hh)/2);ctx.fill();ctx.restore()}ctx.globalAlpha=1;}
function frame(now){raf=0;if(document.hidden)return;draw(now);if(!reduced.matches)raf=requestAnimationFrame(frame)}function restart(){cancelAnimationFrame(raf);raf=0;last=0;if(!document.hidden){draw(performance.now());if(!reduced.matches)raf=requestAnimationFrame(frame)}}
addEventListener('resize',resize);addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;mouse.active=true},{passive:true});addEventListener('pointerout',e=>{if(!e.relatedTarget)mouse.active=false},{passive:true});addEventListener('touchend',()=>mouse.active=false,{passive:true});document.addEventListener('visibilitychange',restart);reduced.addEventListener('change',restart);resize();restart();})();
